    void refresh(){if(stage==null)return;track=Math.max(0,Math.min(doc.tracks.size()-1,track));frame=Math.max(0,Math.min(doc.frames-1,frame));for(int i=0;i<tools.size();i++)tools.get(i).setBackgroundColor(i==tool?0xff257f84:0xff292e43);swatch(fillButton,fill);swatch(strokeButton,stroke);info.setText(names()[tool]+" · "+doc.tracks.get(track).name+" · "+L10n.t("Кадр")+" "+(frame+1)+" / "+doc.frames+" · "+VectorDocument.n(doc.fps)+" FPS"+(doc.tracks.get(track).locked?" · "+L10n.t("Заблокирован"):""));scrub.setMax(doc.frames-1);scrub.setProgress(frame);VectorIcon.install(play,playing?"Ⅱ":"▶");VectorMedia.update(this);stage.invalidate();sheet.invalidate();}
