    void nodeKind(){VectorDocument.Shape s=primary();if(s==null||node<0||node>=s.nodes.size()||!writable())return;snapshot();s=editable(s.id);VectorDocument.Node p=s.nodes.get(node);if(Math.hypot(p.ix,p.iy)+Math.hypot(p.ox,p.oy)>.0001){p.ix=p.iy=p.ox=p.oy=0;}else{int count=s.nodes.size();VectorDocument.Node a=s.nodes.get(s.closed?(node+count-1)%count:Math.max(0,node-1)),b=s.nodes.get(s.closed?(node+1)%count:Math.min(count-1,node+1));p.ox=(b.x-a.x)/6;p.oy=(b.y-a.y)/6;p.ix=-p.ox;p.iy=-p.oy;}refresh();}
    void tween(){stop();stage.finishPen();Integer from=layer().keys.floorKey(frame),to=layer().keys.higherKey(frame);if(from==null||to==null){notice(L10n.t("Создайте следующий ключ с копией тех же объектов, затем переместите их или измените узлы."));return;}if(!VectorDocument.compatible(layer().keys.get(from),layer().keys.get(to))){notice(L10n.t("Для твина нужны одинаковые объекты и одинаковое число узлов в двух ключах."));return;}if(!writable())return;new AlertDialog.Builder(activity).setTitle(L10n.t("Твин движения и формы")).setItems(new String[]{L10n.t("Отключить твин"),L10n.t("Линейно"),"Easy Ease",L10n.t("Плавное начало"),L10n.t("Плавный конец")},(d,n)->{snapshot();VectorDocument.Cel c=layer().keys.get(from);c.tween=n>0;c.ease=Math.max(0,n-1);refresh();}).show();}
    void widthDialog(){LinearLayout box=box();EditText w=field(box,L10n.t("Толщина обводки"),VectorDocument.n(width),true),smooth=field(box,L10n.t("Сглаживание карандаша 0…1"),VectorDocument.n(smoothing),true);form(L10n.t("Кисть и карандаш"),box,()->{double v=number(w,0,100000),s=number(smooth,0,1);if(!selected.isEmpty()&&writable()){snapshot();for(VectorDocument.Shape shape:edit().shapes)if(selected.contains(shape.id))shape.strokeWidth=v;}width=v;smoothing=s;refresh();});}
