    void applyColor(boolean line,int color){if(!selected.isEmpty()&&writable()){snapshot();for(VectorDocument.Shape s:edit().shapes)if(selected.contains(s.id)){if(line)s.stroke=color;else if(s.closed||s.isText())s.fill=color;}}if(line)stroke=color;else fill=color;refresh();}
