    double number(EditText e,double low,double high){double n=Double.parseDouble(e.getText().toString().trim().replace(',','.'));if(!Double.isFinite(n)||n<low||n>high){e.setError(low+"…"+high);throw new IllegalArgumentException(L10n.t("Проверьте числовые параметры"));}return n;}
    void properties(){VectorDocument.Shape s=primary();if(s==null)return;final String id=s.id;LinearLayout b=box();EditText objectName=field(b,L10n.t("Имя объекта"),s.name,false);EditText x=field(b,"X",VectorDocument.n(s.x),true),y=field(b,"Y",VectorDocument.n(s.y),true),sx=field(b,L10n.t("Масштаб X"),VectorDocument.n(s.sx),true),sy=field(b,L10n.t("Масштаб Y"),VectorDocument.n(s.sy),true),r=field(b,L10n.t("Поворот"),VectorDocument.n(s.angle),true),alpha=field(b,L10n.t("Прозрачность"),VectorDocument.n(s.opacity),true);EditText text=s.isText()?field(b,L10n.t("Текст"),s.text,false):null,size=s.isText()?field(b,L10n.t("Размер текста"),VectorDocument.n(s.fontSize),true):null;
        form(L10n.t("Свойства векторного объекта"),b,()->{if(!writable())return;double px=number(x,-1000000,1000000),py=number(y,-1000000,1000000),ax=number(sx,-1000,1000),ay=number(sy,-1000,1000),angle=number(r,-1000000,1000000),a=number(alpha,0,1),font=size==null?48:number(size,1,100000);if(Math.abs(ax)<.00001||Math.abs(ay)<.00001)throw new IllegalArgumentException(L10n.t("Масштаб не должен быть нулевым"));if(text!=null&&text.getText().toString().isEmpty())throw new IllegalArgumentException(L10n.t("Введите текст"));snapshot();VectorDocument.Shape next=editable(id);next.name=objectName.getText().toString();next.x=px;next.y=py;next.sx=ax;next.sy=ay;next.angle=angle;next.opacity=a;if(text!=null){next.text=text.getText().toString();next.fontSize=font;}refresh();});}
    void textAt(double x,double y){if(!writable())return;LinearLayout b=box();EditText input=field(b,L10n.t("Текст"),L10n.t("Текст"),false),size=field(b,L10n.t("Размер текста"),"48",true);form(L10n.t("Текстовый объект"),b,()->{String content=input.getText().toString();double font=number(size,1,100000);if(content.isEmpty())throw new IllegalArgumentException(L10n.t("Введите текст"));snapshot();VectorDocument.Shape s=new VectorDocument.Shape();s.text=content;s.fontSize=font;s.x=x;s.y=y;s.fill=fill;s.strokeWidth=0;edit().shapes.add(s);selected.clear();selected.add(s.id);refresh();});}
    void layers(){stop();stage.finishPen();ArrayList<String> list=new ArrayList<String>();list.add(L10n.t("Добавить слой рисунка"));list.add(L10n.t("Настройки выбранного слоя"));list.add(L10n.t("Удалить выбранный слой"));list.add(L10n.t("Поднять слой"));list.add(L10n.t("Опустить слой"));for(int i=doc.tracks.size()-1;i>=0;i--){VectorDocument.Track t=doc.tracks.get(i);list.add((i==track?"● ":"○ ")+(t.visible?"":"◌ ")+(t.locked?"🔒 ":"")+t.name);}new AlertDialog.Builder(activity).setTitle(L10n.t("Слои рисунков")).setItems(list.toArray(new String[0]),(d,n)->{if(n==0){snapshot();doc.tracks.add(new VectorDocument.Track(L10n.t("Рисунок")+" "+(doc.tracks.size()+1)));track=doc.tracks.size()-1;selected.clear();refresh();}else if(n==1)layerProperties();else if(n==2){snapshot();doc.tracks.remove(track);if(doc.tracks.isEmpty())doc.tracks.add(new VectorDocument.Track(L10n.t("Рисунок 1")));track=Math.min(track,doc.tracks.size()-1);selected.clear();refresh();}else if(n==3||n==4){int next=track+(n==3?1:-1);if(next>=0&&next<doc.tracks.size()){snapshot();Collections.swap(doc.tracks,track,next);track=next;refresh();}}else{track=doc.tracks.size()-1-(n-5);selected.clear();node=-1;refresh();}}).show();}
